const enc=new TextEncoder();
const page=(body)=>new Response('<!doctype html><html><meta name="viewport" content="width=device-width,initial-scale=1"><title>ReviewTap</title><style>body{font:16px system-ui;background:#f8f5f0;color:#2b211c;margin:0}main{max-width:1100px;margin:35px auto;padding:24px}header{background:#251b18;color:white;padding:22px 30px}h1{margin:0}button,input,select{font:inherit;padding:10px;border:1px solid #cad2e2;border-radius:8px}button{background:#76503c;color:white;cursor:pointer}article{background:white;border-radius:14px;padding:20px;margin:18px 0;box-shadow:0 2px 10px #ddd}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #ddd;text-align:left}input{max-width:95%}a{color:#76503c}.scroll{overflow:auto}</style><header><h1>ReviewTap</h1></header><main>'+body+'</main></html>',{headers:{'content-type':'text/html;charset=utf-8','cache-control':'no-store','x-frame-options':'DENY','content-security-policy':"default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; base-uri 'none'; frame-ancestors 'none'"}});
const json=(o,s=200)=>new Response(JSON.stringify(o),{status:s,headers:{'content-type':'application/json','cache-control':'no-store'}});
const idok=s=>/^[a-f0-9]{16}$/.test(s);
const cookie=r=>(r.headers.get('cookie')||'').split(';').map(x=>x.trim()).find(x=>x.startsWith('rt='))?.slice(3);
async function sig(secret,payload){const key=await crypto.subtle.importKey('raw',enc.encode(secret),{name:'HMAC',hash:'SHA-256'},false,['sign']);return [...new Uint8Array(await crypto.subtle.sign('HMAC',key,enc.encode(payload)))].map(b=>b.toString(16).padStart(2,'0')).join('');}
async function authorized(req,env){if(!env.SESSION_SECRET)return false;const v=cookie(req);if(!v)return false;const [expiry,mac]=v.split('.');if(!/^\d+$/.test(expiry)||Number(expiry)<Date.now()||!/^[a-f0-9]{64}$/.test(mac||''))return false;return (await sig(env.SESSION_SECRET,expiry))===mac;}
const validUrl=s=>{try{const u=new URL(s);return u.protocol==='https:'&&!u.username&&!u.password&&s.length<=2000;}catch{return false;}};


